// Functional tests of Marks and Gleanings (#13, PRD 4.4.2, 4.4.4) through the HTTP API, with Books generated by
// playing the worker over /internal.
import { and, eq } from "drizzle-orm";
import { describe, expect, it } from "vitest";
import type { BookDetail, Gleaning, MarkResult, ParseResult } from "../src/contract.js";
import { allowlist, marks } from "../src/db/schema.js";
import { markProcessed } from "../src/marks/marks.js";
import { generatedBook, logIn, testApp, withCookie, type TestApp } from "./helpers.js";

type T = Awaited<ReturnType<typeof testApp>>;
const sentence = (text: string) => ({ paragraphIndex: 0, text, spokenText: text });

/** Rendered 4 s per Sentence: I runs 0 to 8 s, II 8 to 12 s. */
const CHAPTERS: ParseResult["chapters"] = [
  { title: "I", sentences: [sentence("It is a truth universally acknowledged."), sentence("However little known.")] },
  { title: "II", sentences: [sentence("Mr. Bennet was among the earliest.")] },
];

/** The Book's Sentence ids in reading order. */
async function sentenceIds(app: TestApp, book: BookDetail): Promise<string[]> {
  const ids: string[] = [];
  for (const c of book.chapters) {
    const rows = (await (await app.request(`/api/chapters/${c.id}/sentences`)).json()) as { id: string }[];
    ids.push(...rows.map((s) => s.id));
  }
  return ids;
}

async function mark(app: TestApp, sentenceId: string) {
  const res = await app.request(`/api/sentences/${sentenceId}/mark`, { method: "PUT" });
  return { status: res.status, body: res.status === 200 ? ((await res.json()) as MarkResult) : null };
}

const unmark = (app: TestApp, sentenceId: string) => app.request(`/api/sentences/${sentenceId}/mark`, { method: "DELETE" });
const dismiss = (app: TestApp, sentenceId: string) =>
  app.request(`/api/sentences/${sentenceId}/mark/dismiss`, { method: "POST" });

async function gleanings(app: TestApp): Promise<Gleaning[]> {
  const res = await app.request("/api/gleanings");
  expect(res.status).toBe(200);
  return (await res.json()) as Gleaning[];
}

async function gleaningCount(app: TestApp): Promise<number> {
  return ((await (await app.request("/api/gleanings/count")).json()) as { count: number }).count;
}

async function pendingInBook(app: TestApp, bookId: string): Promise<string[]> {
  const res = await app.request(`/api/books/${bookId}/marks`);
  expect(res.status).toBe(200);
  return ((await res.json()) as { pending: string[] }).pending;
}

/** A user with one generated Book; returns the Book and its Sentence ids. */
async function withBook(t: T, name = "Pride and Prejudice") {
  const book = await generatedBook(t, name, CHAPTERS);
  return { book, ids: await sentenceIds(t.app, book) };
}

describe("marking a Sentence (PRD 4.4.2)", () => {
  it("creates a pending Mark that shows up in the Book's pending Marks and in Gleanings", async () => {
    const t = await testApp();
    const { book, ids } = await withBook(t);

    expect(await mark(t.app, ids[1]!)).toEqual({ status: 200, body: { result: "created" } });

    expect(await pendingInBook(t.app, book.id)).toEqual([ids[1]]);
    expect(await gleanings(t.app)).toEqual([
      {
        sentenceId: ids[1],
        text: "However little known.",
        bookId: book.id,
        bookTitle: "Pride and Prejudice",
        chapterId: book.chapters[0]!.id,
        chapterTitle: "I",
        startMs: 4000,
        markedAt: "2026-11-18T00:00:00.000Z",
      },
    ]);
    expect(await gleaningCount(t.app)).toBe(1);
  });

  it("does not mark a pending Sentence twice (AC-MARK-03)", async () => {
    const t = await testApp();
    const { ids } = await withBook(t);
    await mark(t.app, ids[0]!);

    expect(await mark(t.app, ids[0]!)).toEqual({ status: 200, body: { result: "already" } });
    expect(await gleaningCount(t.app)).toBe(1);
  });

  it("puts a processed or dismissed Mark back into Gleanings, on top (AC-MARK-04)", async () => {
    const t = await testApp();
    const { ids } = await withBook(t);
    await mark(t.app, ids[0]!);
    t.clock.advance(1000);
    await mark(t.app, ids[1]!);
    const [row] = await t.db.select().from(marks).where(eq(marks.sentenceId, ids[0]!));
    // A Card made from the Sentence processes its Mark (#15).
    await markProcessed(t.db, row!.userId, ids[0]!, t.clock.now());
    expect((await gleanings(t.app)).map((g) => g.sentenceId)).toEqual([ids[1]]);
    t.clock.advance(1000);
    expect((await dismiss(t.app, ids[1]!)).status).toBe(204);
    expect(await gleanings(t.app)).toEqual([]);

    t.clock.advance(1000);
    expect((await mark(t.app, ids[1]!)).body).toEqual({ result: "reopened" });
    t.clock.advance(1000);
    expect((await mark(t.app, ids[0]!)).body).toEqual({ result: "reopened" });

    expect((await gleanings(t.app)).map((g) => [g.sentenceId, g.markedAt])).toEqual([
      [ids[0], "2026-11-18T00:00:04.000Z"],
      [ids[1], "2026-11-18T00:00:03.000Z"],
    ]);
  });

  it("deletes the Mark on undo or 取消标记, and takes it out of Gleanings (AC-MARK-05)", async () => {
    const t = await testApp();
    const { book, ids } = await withBook(t);
    await mark(t.app, ids[2]!);

    expect((await unmark(t.app, ids[2]!)).status).toBe(204);

    expect(await t.db.select().from(marks)).toEqual([]);
    expect(await pendingInBook(t.app, book.id)).toEqual([]);
    // Undoing again (a replayed offline request) is not an error.
    expect((await unmark(t.app, ids[2]!)).status).toBe(204);
  });

  it("refuses Sentences of Books not on the user's Shelf, and unknown ones", async () => {
    const t = await testApp();
    const { book, ids } = await withBook(t);
    await t.db.insert(allowlist).values({ email: "other@example.com" });
    const other = withCookie(t.anon, await logIn(t, "other@example.com"));

    expect((await mark(other, ids[0]!)).status).toBe(404);
    expect((await other.request(`/api/books/${book.id}/marks`)).status).toBe(404);
    expect((await mark(t.app, "00000000-0000-4000-8000-000000000000")).status).toBe(404);
    expect((await mark(t.app, "not-a-uuid")).status).toBe(400);

    await mark(t.app, ids[0]!);
    expect((await unmark(other, ids[0]!)).status).toBe(204);
    expect((await dismiss(other, ids[0]!)).status).toBe(404);
    expect(await gleaningCount(t.app)).toBe(1);
    expect(await gleanings(other)).toEqual([]);
  });

  it("keeps each user's Marks to themselves", async () => {
    const t = await testApp();
    const { ids } = await withBook(t);
    await mark(t.app, ids[0]!);
    await t.db.insert(allowlist).values({ email: "other@example.com" });
    const other = withCookie(t.anon, await logIn(t, "other@example.com"));

    expect(await gleaningCount(other)).toBe(0);
  });
});

describe("Gleanings (PRD 4.4.4)", () => {
  it("lists pending Marks across Books, most recently marked first (AC-GLEAN-01)", async () => {
    const t = await testApp();
    const a = await withBook(t, "A");
    const b = await withBook(t, "B");
    await mark(t.app, a.ids[0]!);
    t.clock.advance(1000);
    await mark(t.app, b.ids[2]!);
    t.clock.advance(1000);
    await mark(t.app, a.ids[1]!);

    const list = await gleanings(t.app);
    expect(list.map((g) => [g.bookTitle, g.text])).toEqual([
      ["A", "However little known."],
      ["B", "Mr. Bennet was among the earliest."],
      ["A", "It is a truth universally acknowledged."],
    ]);
    // Positions are in the Book's whole audio, so 从这里播放 can seek there.
    expect(list[1]!.startMs).toBe(8000);
    expect(list[1]!.chapterTitle).toBe("II");
  });

  it("dismisses a pending Mark (AC-GLEAN-03): it leaves Gleanings and the count drops", async () => {
    const t = await testApp();
    const { book, ids } = await withBook(t);
    await mark(t.app, ids[0]!);
    await mark(t.app, ids[1]!);

    expect((await dismiss(t.app, ids[0]!)).status).toBe(204);

    expect((await gleanings(t.app)).map((g) => g.sentenceId)).toEqual([ids[1]]);
    expect(await gleaningCount(t.app)).toBe(1);
    expect(await pendingInBook(t.app, book.id)).toEqual([ids[1]]);
    const [row] = await t.db.select().from(marks).where(and(eq(marks.sentenceId, ids[0]!)));
    expect(row!.status).toBe("dismissed");
  });

  it("refuses to dismiss a Sentence without a Mark", async () => {
    const t = await testApp();
    const { ids } = await withBook(t);
    expect((await dismiss(t.app, ids[0]!)).status).toBe(404);
  });

  it("goes with its Book when the Book is deleted", async () => {
    const t = await testApp();
    const { book, ids } = await withBook(t);
    await mark(t.app, ids[0]!);

    expect((await t.app.request(`/api/books/${book.id}`, { method: "DELETE" })).status).toBe(204);

    expect(await gleanings(t.app)).toEqual([]);
    expect(await t.db.select().from(marks)).toEqual([]);
  });
});
